          sbn.addEventListener('click', function () { sbn.disabled = true; api('PUT', 'star', { staff_id: +sw.value, note: sn.value.trim() }).then(function (r) { sbn.disabled = false; if (!r.ok) return oops(r); toast('Employee of the week pinned.'); go('#home'); }).catch(noop); });
          ps.appendChild(add(h('div', 'inline inline--wrap'), sw, sn, sbn, star ? delBtn('Remove', 'btn btn--sm', function () { del('star', 'Employee of the week removed.', function () { go('#home'); }); }) : null));
