    add(who, h('span', 'row__name', x.title), x.note ? h('span', 'row__type', x.note) : null,
      h('span', 'row__meta', (showOwner ? 'For: ' + (x.assigned_name || '—') + ' · ' : '') + (x.created_by !== x.assigned_to ? 'From: ' + (x.creator_name || '—') : 'Personal task')));
    var due = h('span', 'due', x.due ? fmtDay(x.due) : 'No due date');
